 static int count;
 static void Check(bool ok,string label){if(!ok)throw new Exception("Chemical FAIL "+count+" "+label);count++;File.WriteAllText("Temp/chemical-industry-progress.txt",count+" "+label);}
 static void Near(float a,float b,string label)=>Check(Mathf.Abs(a-b)<.01f,label+" "+a+"/"+b);
 static async Task Wait(Func<bool> ready,int seconds=90){var end=DateTime.UtcNow.AddSeconds(seconds);while(!ready()&&DateTime.UtcNow<end)await Task.Delay(70);}
 static T Put<T>(B kind,Vector3 at)where T:BuildingBase{var template=(GameObject)typeof(BuildingPlacementController).GetMethod("GetTemplate",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{kind,AntColony.Data.UnitRole.Worker});var go=Object.Instantiate(template,at,Quaternion.identity);go.name=kind.ToString();go.SetActive(true);return go.GetComponent<T>();}
 static float Floor(R type)=>ResourceNode.Available.Where(n=>n.IsLooseCargo&&n.ResourceType==type).Sum(n=>n.AmountRemaining);
 static void Park(CommanderAnt c,Processor bench){c.CommandStop();Check(c.StartService(bench,CommanderJobs.Crafting),"onsite chemical assignment");c.Agent.Warp(c.Agent.destination);c.Agent.ResetPath();}
 public static async Task<string> Main()
 {
  count=0;Time.timeScale=0;var old=UserSettings.Current.Clone();var root=SaveStorage.RootOverride;SaveStorage.RootOverride=Path.Combine(Application.temporaryCachePath,"Chemical1028-"+Guid.NewGuid().ToString("N"));
  try
  {
   var config=old.Clone();config.autoSaveEnabled=false;config.autoPauseThreat=config.autoPauseDowned=config.autoPauseRocket=false;UserSettings.Apply(config,false);await Wait(()=>!SaveSystem.Busy);
   StartingCandidate[] team;do{team=Enumerable.Range(0,3).Select(StartingCandidate.Roll).ToArray();}while(StartingCandidate.Missing(team).Length>0);foreach(var t in team){t.ageYears=20;t.traits.values.Clear();}
   SaveSystem.NewGame(new NewGameOptions{seed=281028,mapSize=MapSize.Small,startingCount=3,startingTeam=team});await Wait(()=>!SaveSystem.Busy&&CommanderRoster.Instance.Commanders.Count==3);AntColony.UI.GameMenuController.Instance.Resume();Time.timeScale=0;GameSession.Instance.MarkStarted(gameSeconds:20);
   foreach(var p in CommanderRoster.Instance.Commanders){p.CommandStop();p.SetJobEnabled(CommanderJobs.All,false);p.PersonalState.sleep=new CommanderSleepState();p.PersonalState.meal=new CommanderMealState();p.PersonalState.hygiene=new CommanderHygieneState();p.PersonalState.joy=new CommanderJoyState();}
   Check(!ScienceEffects.BuildingUnlocked(B.ChemistryBench),"chemical bench requires existing industry research");var research=CampaignResearch.Instance;var rs=research.CaptureState();rs.completed.Add((int)ScienceTechnology.UndergroundSurvey);research.RestoreState(rs);Check(ScienceEffects.BuildingUnlocked(B.ChemistryBench),"research unlocks chemical bench");Check(StoreBin.TypeCount==Enum.GetValues(typeof(R)).Length,"plastic retained in expanded storage catalog");
   var c=CommanderRoster.Instance.Commanders.First();var id=c.PersonalState.id;Check(NavMesh.SamplePosition(c.Position+Vector3.right*8,out var hit,5,NavMesh.AllAreas),"reachable chemical station");var at=new Vector3(Mathf.Floor(hit.position.x)+.5f,hit.position.y,Mathf.Floor(hit.position.z)+.5f);
   var bench=Put<Processor>(B.ChemistryBench,at);var pipe=Put<SupplyFacility>(B.FluidPipe,at+Vector3.right*2);var tank=Put<SupplyFacility>(B.FluidTank,at+Vector3.right*3);var gas=Put<SupplyFacility>(B.GasTank,at-Vector3.forward);gas.Fill(R.NaturalGas,10);var battery=Put<PowerNode>(B.Battery,at+Vector3.forward);typeof(PowerNode).GetProperty("Charge").SetValue(battery,GameBalance.BatteryCapacity);var generator=Put<PowerNode>(B.SteamGenerator,at+Vector3.forward*2);var store=Put<Storage>(B.Storage,c.Position+Vector3.left*3);ResourceManager.Instance.AddTo(store.Bin,R.Coal,20);generator.RestoreFuel(10);PowerGrid.Tick(.5f);
