   pipe.transform.position+=Vector3.forward*12;var progress=bench.Progress;Time.timeScale=1;Check(bench.Work(c,.1f)&&bench.Progress>progress&&tank.Supply.amount==4,"already supplied batch continues after pipe disconnection");bench.Powered=false;progress=bench.Progress;Check(!bench.Work(c,20)&&bench.Progress==progress,"outage preserves progress and prepaid oil");bench.Powered=true;Time.timeScale=0;Check(!bench.Work(c,20),"paused game cannot consume work");bench.Paused=true;Check(c.ServiceTarget==null&&!bench.NeedsWork,"order pause releases worker");bench.Paused=false;Park(c,bench);
   Check(SaveSystem.TrySave(false,0,out var error),"prepaid chemical save: "+error);Check(SaveValidator.TryParse(File.ReadAllText(SaveSlots.PathFor(false,0)),out var saved,out error),"saved chemical state parses");var dto=saved.buildings.Single(b=>b.kind=="ChemistryBench");dto.processor.bufferedOil=1;Check(!SavePreflight.Validate(saved,out error),"reject incomplete raw buffer for active batch");dto.processor.bufferedOil=2;dto.processor.gasPaid=false;Check(!SavePreflight.Validate(saved,out error),"reject unpaid active chemical batch");
   Check(SaveSystem.TryLoad(SaveSlots.PathFor(false,0),out error),"chemical scene reload accepted: "+error);await Wait(()=>!SaveSystem.Busy);Time.timeScale=0;bench=SceneObjects.All<Processor>().Single(p=>p.Chemical);c=CommanderRoster.Instance.Commanders.First(p=>p.PersonalState.id==id);tank=SupplyFacility.All.Single(s=>s.Kind==B.FluidTank);pipe=SupplyFacility.All.Single(s=>s.Kind==B.FluidPipe);bench.Powered=true;
   Check(bench.BufferedOil==2&&bench.Current?.output==R.Plastic&&bench.MakerId==id&&c.ServiceTarget==bench,"buffer order maker and service survive reload");Time.timeScale=1;var plastic=Floor(R.Plastic);await Wait(()=>bench.Current==null,30);Check(bench.Current==null,"restored supplied batch resumes in real frames without pipeline");Time.timeScale=0;Near(Floor(R.Plastic)-plastic,1,"one real plastic output on floor");Check(bench.BufferedOil==0&&bench.Current==null&&tank.Supply.amount==4,"completion cannot charge raw oil twice");c.CommandStop();
   pipe.transform.position=bench.Position+Vector3.right*2;bench.AddOrder(0,Workshop.OrderMode.KeepStock,1);Check(!bench.NeedsWork,"keep stock counts unhauled plastic");bench.RemoveOrder(bench.Orders.Single());bench.AddOrder(0,Workshop.OrderMode.Count,1);Park(c,bench);Time.timeScale=1;Check(bench.Work(c,.1f)&&tank.Supply.amount==2,"new batch supplied exactly once");Time.timeScale=0;bench.CancelCurrent();Check(bench.BufferedOil==1&&bench.Current==null,"cancel retains normal seventy percent refund as internal liquid");bench.CancelCurrent();Check(bench.BufferedOil==1&&tank.Supply.amount==2,"repeat cancellation cannot duplicate fluid");bench.AddOrder(0,Workshop.OrderMode.Count,1);Park(c,bench);Time.timeScale=1;Check(bench.Work(c,.1f)&&tank.Supply.amount==1,"reuses refunded raw oil and takes only missing one");Check(bench.Work(c,1000),"reused raw batch completes");Time.timeScale=0;c.CommandStop();Check(Floor(R.Plastic)==2&&bench.BufferedOil==0,"two finished outputs and refund conservation");
   tank.Fill(R.CrudeOil,5);bench.AddOrder(0,Workshop.OrderMode.Count,1);typeof(DiplomacyManager).GetMethod("DropFloor",BindingFlags.Static|BindingFlags.NonPublic,null,new[]{typeof(R),typeof(int),typeof(Vector3)},null).Invoke(null,new object[]{R.Stone,100,bench.Position});var before=tank.Supply.amount;Check(!bench.NeedsWork&&!bench.Work(c,1)&&tank.Supply.amount==before&&bench.WaitReason.Contains("출력"),"full floor output stops before consuming raw oil");foreach(var n in ResourceNode.Available.Where(n=>n.IsLooseCargo&&n.ResourceType==R.Stone&&(n.transform.position-bench.Position).sqrMagnitude<16).ToArray())n.TryConsumeStock(n.AmountRemaining);Check(bench.NeedsWork,"clearing output resumes readiness");
   var model=bench.GetComponent<FacilityVisual>();Check(model!=null&&model.Model!=null&&bench.GetComponent<Renderer>().forceRenderingOff,"real chemical FBX hides primitive fallback");await Task.Delay(80);var floorNode=ResourceNode.Available.First(n=>n.IsLooseCargo&&n.ResourceType==R.Plastic&&n.AmountRemaining>=1);Check(floorNode.transform.Find("ResourceModel")!=null&&floorNode.GetComponent<Renderer>().forceRenderingOff,"plastic FBX replaces floor primitive");
   var placement=SceneObjects.Any<BuildingPlacementController>();Check(placement.BeginSciencePlacement(B.ChemistryBench)&&placement.PendingKind==B.ChemistryBench,"chemical construction route connected");placement.CancelPlacement();var cost=EarlyConstruction.Cost(B.ChemistryBench);Check(cost.Any(x=>x.type==R.Steel&&x.amount==10)&&cost.Any(x=>x.type==R.Copper&&x.amount==5),"reuses declared industrial build costs");
   AntColony.UI.GameMenuController.Instance.ShowProcessor(bench);var texts=AntColony.UI.GameMenuController.Instance.GetComponentsInChildren<UnityEngine.UI.Text>().Select(t=>t.text).ToArray();Check(texts.Any(t=>t.Contains("배관 원유"))&&texts.Any(t=>t.Contains("내부 원유")),"processing UI shows real fluid cost and retained oil");AntColony.UI.GameMenuController.Instance.Resume();Time.timeScale=0;
   Check(SaveSystem.TrySave(false,1,out error),"final chemical and plastic state valid: "+error);var result="PASS "+count+" chemical power, real work, piped raw conservation, refund, save, models and UI checks";File.WriteAllText("Temp/chemical-industry-result.txt",result);return result;
  }
  catch(Exception e){File.WriteAllText("Temp/chemical-industry-result.txt",e.ToString());throw;}
  finally{Time.timeScale=0;SaveStorage.RootOverride=root;UserSettings.Apply(old,false);}
